# SPDX-License-Identifier: GPL-3.0-or-later
"""Opt-in GPU copy-back CPU scan and idle snapshot budget experiments."""
import argparse
from pathlib import Path

PATH = Path("crates/victory-gpu/src/shadow.rs")
REPLACEMENTS = (
    ("fn merge_piece(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    let mut differs = 0u8;",
     "fn merge_piece(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    if sparse_merge_on() {\n        return merge_sparse(now, held, title);\n    }\n    merge_dense(now, held, title)\n}\n\nfn sparse_merge_on() -> bool {\n    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();\n    *ON.get_or_init(|| std::env::var_os(\"VICTORY_BACK_SPARSE_MERGE\").is_some_and(|v| v == \"1\"))\n}\n\n// Compare completed CPU-visible snapshots, not inferred shader dirtiness.\n// Exact equality skips a merge without touching the held or title bytes.\nfn merge_sparse(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    let n = now.len().min(held.len()).min(title.len());\n    let mut changed = false;\n    for at in (0..n).step_by(256) {\n        let end = (at + 256).min(n);\n        if now[at..end] != held[at..end] {\n            changed |= merge_dense(&now[at..end], &mut held[at..end], &mut title[at..end]);\n        }\n    }\n    changed\n}\n\nfn merge_dense(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    let mut differs = 0u8;"),
    ("fn first_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());\n    let (a_chunks, a_tail) = a[..len].as_chunks::<DIFF_CHUNK>();\n    let (b_chunks, b_tail) = b[..len].as_chunks::<DIFF_CHUNK>();\n    let (offset, a, b) = match a_chunks.iter().zip(b_chunks).position(|(x, y)| x != y) {\n        Some(i) => (i * DIFF_CHUNK, &a_chunks[i][..], &b_chunks[i][..]),\n        None => (len - a_tail.len(), a_tail, b_tail),\n    };\n    a.iter().zip(b).position(|(x, y)| x != y).map(|i| offset + i)\n}\n\n",
     "fn first_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    #[cfg(target_arch = \"x86_64\")]\n    if avx_diff_on() {\n        // SAFETY: feature detection in avx_diff_on.\n        return unsafe { avx_difference(a, b, false) };\n    }\n    first_difference_scalar(a, b)\n}\n\n#[cfg(target_arch = \"x86_64\")]\nfn avx_diff_on() -> bool {\n    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();\n    *ON.get_or_init(|| std::env::var_os(\"VICTORY_BACK_AVX2\").is_some_and(|v| v == \"1\")\n        && std::is_x86_feature_detected!(\"avx2\"))\n}\n\n// Read only the common slice length, with unaligned loads and exact\n// byte masks. Reverse scans use the same masks in the opposite order.\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx2\")]\nunsafe fn avx_difference(a: &[u8], b: &[u8], reverse: bool) -> Option<usize> {\n    use core::arch::x86_64::{__m256i, _mm256_loadu_si256, _mm256_cmpeq_epi8, _mm256_movemask_epi8};\n    let n = a.len().min(b.len());\n    let full = n / 32;\n    let tail = full * 32;\n    let diff = |at: usize| -> u32 {\n        // SAFETY: callers only pass complete 32-byte chunks; AVX2 checked.\n        unsafe {\n            let x = _mm256_loadu_si256(a.as_ptr().add(at).cast::<__m256i>());\n            let y = _mm256_loadu_si256(b.as_ptr().add(at).cast::<__m256i>());\n            !(_mm256_movemask_epi8(_mm256_cmpeq_epi8(x, y)) as u32)\n        }\n    };\n    if reverse {\n        if let Some(i) = a[tail..n].iter().zip(&b[tail..n]).rposition(|(x, y)| x != y) {\n            return Some(tail + i);\n        }\n        for k in (0..full).rev() {\n            let d = diff(k * 32);\n            if d != 0 { return Some(k * 32 + (31 - d.leading_zeros()) as usize); }\n        }\n    } else {\n        for k in 0..full {\n            let d = diff(k * 32);\n            if d != 0 { return Some(k * 32 + d.trailing_zeros() as usize); }\n        }\n        return a[tail..n].iter().zip(&b[tail..n]).position(|(x, y)| x != y).map(|i| tail + i);\n    }\n    None\n}\n\nfn first_difference_scalar(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());\n    let (a_chunks, a_tail) = a[..len].as_chunks::<DIFF_CHUNK>();\n    let (b_chunks, b_tail) = b[..len].as_chunks::<DIFF_CHUNK>();\n    let (offset, a, b) = match a_chunks.iter().zip(b_chunks).position(|(x, y)| x != y) {\n        Some(i) => (i * DIFF_CHUNK, &a_chunks[i][..], &b_chunks[i][..]),\n        None => (len - a_tail.len(), a_tail, b_tail),\n    };\n    a.iter().zip(b).position(|(x, y)| x != y).map(|i| offset + i)\n}\n\n"),
    ("fn last_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());\n    let (a_chunks, a_tail) = a[..len].as_chunks::<DIFF_CHUNK>();\n    let (b_chunks, b_tail) = b[..len].as_chunks::<DIFF_CHUNK>();\n    if let Some(i) = a_tail.iter().zip(b_tail).rposition(|(x, y)| x != y) {\n        return Some(len - a_tail.len() + i);\n    }\n    let chunk = a_chunks.iter().zip(b_chunks).rposition(|(x, y)| x != y)?;\n    a_chunks[chunk]\n        .iter()\n        .zip(&b_chunks[chunk])\n        .rposition(|(x, y)| x != y)\n        .map(|i| chunk * DIFF_CHUNK + i)\n}\n\n",
     "fn last_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    #[cfg(target_arch = \"x86_64\")]\n    if avx_diff_on() {\n        // SAFETY: feature detection in avx_diff_on.\n        return unsafe { avx_difference(a, b, true) };\n    }\n    last_difference_scalar(a, b)\n}\n\nfn last_difference_scalar(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());\n    let (a_chunks, a_tail) = a[..len].as_chunks::<DIFF_CHUNK>();\n    let (b_chunks, b_tail) = b[..len].as_chunks::<DIFF_CHUNK>();\n    if let Some(i) = a_tail.iter().zip(b_tail).rposition(|(x, y)| x != y) {\n        return Some(len - a_tail.len() + i);\n    }\n    let chunk = a_chunks.iter().zip(b_chunks).rposition(|(x, y)| x != y)?;\n    a_chunks[chunk]\n        .iter()\n        .zip(&b_chunks[chunk])\n        .rposition(|(x, y)| x != y)\n        .map(|i| chunk * DIFF_CHUNK + i)\n}\n\n"),
    ("    const KEPT: usize = 512 << 20;\n    let mut pool = POOL.lock().unwrap_or_else(|e| e.into_inner());",
     "    const KEPT: usize = 512 << 20;\n    // Optional hard idle-only budget; no active snapshots are evicted.\n    static CAP: std::sync::OnceLock<Option<usize>> = std::sync::OnceLock::new();\n    let cap = *CAP.get_or_init(|| std::env::var(\"VICTORY_BACK_IDLE_MB\").ok()\n        .and_then(|s| s.parse::<usize>().ok()).and_then(|mb| mb.checked_mul(1 << 20)));\n    if let Some(cap) = cap {\n        let discarded = {\n            let mut pool = POOL.lock().unwrap_or_else(|e| e.into_inner());\n            pool.push(v);\n            trim_idle_pool(&mut pool, cap)\n        };\n        // Large allocations may be expensive to release; not under lock.\n        drop(discarded);\n        return;\n    }\n    let mut pool = POOL.lock().unwrap_or_else(|e| e.into_inner());"),
    ("const NOT_WATCHED: u8 = 2;",
     "// Prefer large reusable buffers that fit, but never exceed the configured\n// capacity budget. Return evicted allocations to the caller for disposal.\nfn trim_idle_pool(pool: &mut Vec<Vec<u8>>, cap: usize) -> Vec<Vec<u8>> {\n    pool.sort_by_key(|v| std::cmp::Reverse(v.capacity()));\n    let mut used = 0usize;\n    let mut keep = Vec::new();\n    let mut discard = Vec::new();\n    for v in pool.drain(..) {\n        if keep.len() < 8 && v.capacity() <= cap.saturating_sub(used) && cap != 0 {\n            used += v.capacity();\n            keep.push(v);\n        } else {\n            discard.push(v);\n        }\n    }\n    *pool = keep;\n    discard\n}\n\n#[cfg(test)]\nmod perf4_tests {\n    use super::*;\n\n    #[test]\n    fn sparse_merge_matches_dense_for_conflicts_and_tails() {\n        for n in [0, 1, 31, 255, 256, 257, 511, 4097] {\n            let old: Vec<u8> = (0..n).map(|i| (i * 13) as u8).collect();\n            for stride in [1, 17, 257, 8192] {\n                let mut gpu = old.clone();\n                let mut cpu = old.clone();\n                for i in (0..n).step_by(stride) { gpu[i] ^= 0x55; }\n                for i in (0..n).step_by(11) { cpu[i] ^= 0x33; }\n                let (mut h1, mut h2) = (old.clone(), old.clone());\n                let (mut t1, mut t2) = (cpu.clone(), cpu);\n                assert_eq!(merge_dense(&gpu, &mut h1, &mut t1), merge_sparse(&gpu, &mut h2, &mut t2));\n                assert_eq!((h1, t1), (h2, t2));\n            }\n        }\n    }\n\n    #[test]\n    fn idle_pool_hard_cap() {\n        let mut pool = vec![Vec::with_capacity(64), Vec::with_capacity(32), Vec::with_capacity(16)];\n        let actual = pool.iter().map(Vec::capacity).sum::<usize>();\n        let discarded = trim_idle_pool(&mut pool, 48);\n        assert!(pool.iter().map(Vec::capacity).sum::<usize>() <= 48);\n        assert_eq!(pool.iter().chain(&discarded).map(Vec::capacity).sum::<usize>(), actual);\n        let _ = trim_idle_pool(&mut pool, 0);\n        assert!(pool.is_empty());\n    }\n\n    #[cfg(target_arch = \"x86_64\")]\n    #[test]\n    fn avx2_matches_scalar_unaligned_and_partial() {\n        if !std::is_x86_feature_detected!(\"avx2\") { return; }\n        for n in [0, 1, 31, 32, 33, 63, 64, 65, 255, 257] {\n            let base = vec![7u8; n + 3];\n            for i in 0..=n {\n                let mut other = base.clone();\n                if i < n { other[i + 1] ^= 0x80; }\n                let a = &base[1..1+n];\n                let b = &other[1..2+n];\n                // SAFETY: checked feature above.\n                unsafe {\n                    assert_eq!(avx_difference(a, b, false), first_difference_scalar(a, b));\n                    assert_eq!(avx_difference(a, b, true), last_difference_scalar(a, b));\n                }\n            }\n        }\n    }\n}\n\nconst NOT_WATCHED: u8 = 2;"),
    ("fn back_piece(\n    host: &mut [u8],\n    old: &[u8],\n    title: &mut Vec<u8>,\n    mask: &mut Vec<u8>,\n    runs: &mut Vec<(usize, usize)>,\n    read: impl FnOnce(usize, &mut [u8]) -> bool,\n) -> Option<(usize, usize)> {\n    runs.clear();\n    // From the first byte that differs to the last: title memory is read\n    // and written there only (a shader that sets a few words of a piece\n    // cost a read, a walk and a write of all 64 KiB of it).\n    let first = first_difference(host, old)?;\n    let last = last_difference(host, old).unwrap_or(first);\n    let n = last + 1 - first;\n    let (host, old) = (&mut host[first..=last], &old[first..=last]);\n    title.clear();\n    title.resize(n, 0);\n    if !read(first, title) {\n        return None;\n    }\n    // Title memory with the GPU's bytes put in; the copy takes the title's\n    // bytes in turn.\n    // Without a branch, so the loop runs many bytes at a time: the GPU's\n    // byte where the copy's byte is not what it was before the submission\n    // and the title left its byte as it was, else the title's. (With the\n    // two searches above this was 44 ms a frame for 970 pieces.)\n    // Where the shader and the title both changed a byte while the GPU ran,\n    // the title's stays: the shader computed its byte from the copy's older\n    // data (one cleared a bit of a record the title had already replaced,\n    // and copying it back broke the title's object: an access violation\n    // through 0xffffffff00000000; PalmVIDev e0b70476, VIctory f39c6c2).\n    mask.clear();\n    mask.resize(n, 0);\n    let mut differs = 0u8;\n    for (((t, h), o), m) in title.iter_mut().zip(host.iter_mut()).zip(old).zip(mask.iter_mut()) {\n        let gpu = if (*h != *o) & (*t == *o) { 0xffu8 } else { 0 };\n        let merged = (*t & !gpu) | (*h & gpu);\n        *m = merged ^ *t;\n        differs |= *m;\n        *t = merged;\n        *h = merged;\n    }\n    if differs == 0 {\n        return None;\n    }\n    let mut i = 0;\n    while i < n {\n        while i < n && mask[i] == 0 {\n            i += 1;\n        }\n        let start = i;\n        while i < n && mask[i] != 0 {\n            i += 1;\n        }\n        if i > start {\n            runs.push((start, i - start));\n        }\n    }\n    Some((first, n))\n}\n\n",
     "fn back_piece(\n    host: &mut [u8],\n    old: &[u8],\n    title: &mut Vec<u8>,\n    mask: &mut Vec<u8>,\n    runs: &mut Vec<(usize, usize)>,\n    read: impl FnOnce(usize, &mut [u8]) -> bool,\n) -> Option<(usize, usize)> {\n    runs.clear();\n    // From the first byte that differs to the last: title memory is read\n    // and written there only (a shader that sets a few words of a piece\n    // cost a read, a walk and a write of all 64 KiB of it).\n    let first = first_difference(host, old)?;\n    let last = last_difference(host, old).unwrap_or(first);\n    let n = last + 1 - first;\n    let (host, old) = (&mut host[first..=last], &old[first..=last]);\n    title.clear();\n    title.resize(n, 0);\n    if !read(first, title) {\n        return None;\n    }\n    // Title memory with the GPU's bytes put in; the copy takes the title's\n    // bytes in turn.\n    // Without a branch, so the loop runs many bytes at a time: the GPU's\n    // byte where the copy's byte is not what it was before the submission\n    // and the title left its byte as it was, else the title's. (With the\n    // two searches above this was 44 ms a frame for 970 pieces.)\n    // Where the shader and the title both changed a byte while the GPU ran,\n    // the title's stays: the shader computed its byte from the copy's older\n    // data (one cleared a bit of a record the title had already replaced,\n    // and copying it back broke the title's object: an access violation\n    // through 0xffffffff00000000; PalmVIDev e0b70476, VIctory f39c6c2).\n    mask.clear();\n    mask.resize(n, 0);\n    let mut differs = 0u8;\n    for (((t, h), o), m) in title.iter_mut().zip(host.iter_mut()).zip(old).zip(mask.iter_mut()) {\n        let gpu = if (*h != *o) & (*t == *o) { 0xffu8 } else { 0 };\n        let merged = (*t & !gpu) | (*h & gpu);\n        *m = merged ^ *t;\n        differs |= *m;\n        *t = merged;\n        *h = merged;\n    }\n    if differs == 0 {\n        return None;\n    }\n    let mut i = 0;\n    while i < n {\n        // Skip exact all-zero blocks in the already computed write mask.\n        // Keep the scalar run boundaries and write semantics unchanged.\n        if sparse_merge_on() {\n            while n - i >= 32 && mask[i..i + 32] == [0u8; 32] {\n                i += 32;\n            }\n        }\n        while i < n && mask[i] == 0 {\n            i += 1;\n        }\n        let start = i;\n        while i < n && mask[i] != 0 {\n            i += 1;\n        }\n        if i > start {\n            runs.push((start, i - start));\n        }\n    }\n    Some((first, n))\n}\n\n#[cfg(test)]\nmod copy_back_mask_tests {\n    use super::*;\n\n    // Independent byte-by-byte oracle. Title writes take precedence; only\n    // GPU-only changes that differ from the title's bytes may be written.\n    fn check(old: &[u8], gpu: &[u8], cpu: &[u8]) {\n        let changed: Vec<_> = (0..old.len()).filter(|&i| gpu[i] != old[i]).collect();\n        let mut host = gpu.to_vec();\n        let mut title = vec![0xa5; 3];\n        let mut mask = vec![0x5a; 7];\n        let mut runs = vec![(99, 99)];\n        let mut asked = Vec::new();\n        let result = back_piece(&mut host, old, &mut title, &mut mask, &mut runs, |first, out| {\n            asked.push((first, out.len()));\n            out.copy_from_slice(&cpu[first..first + out.len()]);\n            true\n        });\n        if changed.is_empty() {\n            assert_eq!(result, None);\n            assert!(asked.is_empty());\n            assert!(runs.is_empty());\n            assert_eq!(host, gpu);\n            return;\n        }\n        let first = changed[0];\n        let last = *changed.last().unwrap();\n        let n = last + 1 - first;\n        assert_eq!(asked, [(first, n)]);\n        let mut expected = cpu.to_vec();\n        let mut expected_mask = vec![0; n];\n        let mut expected_runs: Vec<(usize, usize)> = Vec::new();\n        for i in first..=last {\n            if gpu[i] != old[i] && cpu[i] == old[i] {\n                expected[i] = gpu[i];\n                expected_mask[i-first] = gpu[i] ^ cpu[i];\n                match expected_runs.last_mut() {\n                    Some((at, len)) if *at + *len == i-first => *len += 1,\n                    _ => expected_runs.push((i-first, 1)),\n                }\n            }\n        }\n        assert_eq!(title, expected[first..=last]);\n        assert_eq!(mask, expected_mask);\n        assert_eq!(runs, expected_runs);\n        assert_eq!(result, if expected_runs.is_empty() { None } else { Some((first, n)) });\n        assert_eq!(&host[..first], &gpu[..first]);\n        assert_eq!(&host[first..=last], &expected[first..=last]);\n        assert_eq!(&host[last+1..], &gpu[last+1..]);\n\n        // Model a title write after read, but outside the GPU's exact runs.\n        let mut late_cpu = cpu.to_vec();\n        for i in 0..old.len() {\n            if !expected_runs.iter().any(|&(at, len)| (first+at..first+at+len).contains(&i)) {\n                late_cpu[i] ^= 0x80;\n            }\n        }\n        let mut wrote = late_cpu.clone();\n        for &(at, len) in &runs {\n            wrote[first+at..first+at+len].copy_from_slice(&title[at..at+len]);\n        }\n        for i in 0..old.len() {\n            let wanted = if i >= first && i <= last && expected_mask[i-first] != 0 {\n                expected[i]\n            } else { late_cpu[i] };\n            assert_eq!(wrote[i], wanted, \"offset {i}\");\n        }\n    }\n\n    #[test]\n    fn mask_boundary_patterns_and_title_conflicts() {\n        for n in [0, 1, 2, 31, 32, 33, 63, 64, 65, 255, 256, 257, 1025] {\n            let old: Vec<u8> = (0..n).map(|i| (i * 29 + 5) as u8).collect();\n            for stride in [1, 2, 31, 32, 33, 255, 256, 257] {\n                for offset in [0, 1, 7] {\n                    let (mut gpu, mut cpu) = (old.clone(), old.clone());\n                    for i in (offset..n).step_by(stride) { gpu[i] ^= 0x33; }\n                    for i in (offset..n).step_by(7) { cpu[i] ^= 0x55; }\n                    check(&old, &gpu, &cpu);\n                }\n            }\n        }\n    }\n\n    #[test]\n    fn mask_all_byte_values_and_every_conflict_class() {\n        let old: Vec<u8> = (0..1024).map(|i| (i % 256) as u8).collect();\n        let (mut gpu, mut cpu) = (old.clone(), old.clone());\n        for i in 0..old.len() {\n            match i % 4 {\n                0 => gpu[i] ^= 0xff,\n                1 => cpu[i] ^= 0x81,\n                2 => { gpu[i] ^= 0x77; cpu[i] ^= 0x33; }\n                _ => { gpu[i] ^= 0x44; cpu[i] ^= 0x44; }\n            }\n        }\n        check(&old, &gpu, &cpu);\n        check(&old, &gpu, &gpu);\n        check(&old, &old, &cpu);\n    }\n\n    #[test]\n    fn mask_sparse_far_apart_runs_and_long_contiguous_runs() {\n        let old = vec![0u8; 65536];\n        let mut gpu = old.clone();\n        let mut cpu = old.clone();\n        for i in [0, 31, 32, 63, 64, 255, 256, 32768, 65535] { gpu[i] = 0xff; }\n        gpu[1000..1400].fill(0x80);\n        cpu[1100..1150].fill(0x42);\n        cpu[32768] = 0x77;\n        check(&old, &gpu, &cpu);\n    }\n\n    #[test]\n    fn mask_failed_read_and_no_change_never_emit_stale_runs() {\n        let old = [0u8; 65];\n        let mut host = old;\n        host[31] = 7;\n        host[64] = 9;\n        let original = host;\n        let mut title = vec![0xaa; 128];\n        let mut mask = vec![0xff; 128];\n        let mut runs = vec![(7, 8)];\n        assert_eq!(back_piece(&mut host, &old, &mut title, &mut mask, &mut runs, |first, out| {\n            assert_eq!((first, out.len()), (31, 34));\n            out[0] = 0x99;\n            false\n        }), None);\n        assert_eq!(host, original);\n        assert!(runs.is_empty());\n        host = old;\n        runs.push((1, 2));\n        assert_eq!(back_piece(&mut host, &old, &mut title, &mut mask, &mut runs, |_, _| panic!(\"unexpected read\")), None);\n        assert!(runs.is_empty());\n    }\n\n    #[test]\n    fn mask_deterministic_random_oracle() {\n        let mut state = 0x8d3f_7a12_u64;\n        let mut rand = || {\n            state ^= state << 13;\n            state ^= state >> 7;\n            state ^= state << 17;\n            state\n        };\n        for n in [3, 17, 32, 33, 95, 256, 513, 4096] {\n            for _ in 0..40 {\n                let old: Vec<u8> = (0..n).map(|_| rand() as u8).collect();\n                let (mut gpu, mut cpu) = (old.clone(), old.clone());\n                for i in 0..n {\n                    let bits = rand();\n                    if bits & 3 == 0 { gpu[i] ^= (bits >> 8) as u8; }\n                    if bits & 12 == 0 { cpu[i] ^= (bits >> 16) as u8; }\n                }\n                check(&old, &gpu, &cpu);\n            }\n        }\n    }\n}\n\n"),
)

def transform(source):
    for old, new in REPLACEMENTS:
        if source.count(old) != 1:
            raise ValueError("Expected exactly one pinned source anchor: " + old[:80])
        source = source.replace(old, new, 1)
    return source

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    args = parser.parse_args()
    path = args.checkout / PATH
    try:
        path.write_text(transform(path.read_text(encoding="utf-8")), encoding="utf-8")
    except (OSError, ValueError) as exc:
        parser.exit(1, f"GPU copy preparation failed: {exc}\n")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
